import java.io.*;

public class WriteSerialized {
  public static void main(String[] args) {
    try {
      // 第一步：造一条连接流，连到文件；文件不存在就自动创建
      FileOutputStream fileStream = new FileOutputStream("MyGame.ser");
      // 第二步：造一条链流，挂到连接流上
      ObjectOutputStream os = new ObjectOutputStream(fileStream);
      // 第三步：按顺序写三个对象，不需要碰底下的 fileStream
      os.writeObject(characterOne);
      os.writeObject(characterTwo);
      os.writeObject(characterThree);
      // 第四步：关最上层，整条链连同文件一起关闭
      os.close();
    } catch (IOException ex) {   // I/O 随时可能出问题，必须处理异常
      ex.printStackTrace();
    }
  }
}

import java.io.*;

class ReadAFile {
  public static void main(String[] args) {
    try {
      File myFile = new File("MyText.txt");
      FileReader fileReader = new FileReader(myFile);          // 连接流
      BufferedReader reader = new BufferedReader(fileReader); // 链流，读得更快
      String line;
      // 读到文件末尾返回 null，循环结束
      while ((line = reader.readLine()) != null) {
        System.out.println(line);
      }
      reader.close();
    } catch (IOException e) {
      e.printStackTrace();
    }
  }
}
